    attr_salt: { ko: 'salt (s_u)', en: 'salt (s_u)' },
    attr_uid_hint: { ko: 'uid 는 zkID 내 정보(zkID → 내 계정 → 내 정보)에 있습니다.', en: 'Your uid is on zkID My info (zkID → My account → My info).' },
    attr_salt_hint: { ko: 'salt 는 직접 넣거나 "새로 뽑기" 로 만드세요. 지갑을 처음 등록할 때 지갑 창의 salt 칸에 같은 값을 넣어야 합니다. 이미 등록한 지갑이면 zk 지갑 화면 → 계정 탭 → 상세의 salt 를 넣으세요.', en: 'Type a salt or use "New salt". When you first register your wallet, put the same value into the salt field of the wallet window. If your wallet is already registered, use the salt from zk wallet → Account tab → Details.' },
    attr_salt_gen_btn: { ko: 'salt 새로 뽑기', en: 'New salt' },
