    secrets_mismatch: { where: 'wallet', ko: { title: 'Snap 의 비밀이 등록과 맞지 않습니다', cause: '이 Snap 의 등록 비밀이 지갑 에이전트에 저장된 등록(auid·pk_u)과 다릅니다.', action: '같은 브라우저·같은 Snap 으로 등록했는지 확인하고, 아니면 재시연 세트로 처음부터 등록하세요.' }, en: { title: 'Snap secrets do not match the registration', cause: 'This Snap’s registration secret differs from the registration (auid, pk_u) stored by the wallet agent.', action: 'Make sure you registered with this browser and Snap; otherwise reset and register again.' } },
